import{_ as o,a0 as e,w as s,s as a,ao as x,I as t,x as n,a1 as r,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"4 個最好的 Linux 引導程序 | LCTT x X-CMD","titleTemplate":false,"description":"4 個最好的 Linux 引導程序 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 個最好的 Linux 引導程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 個最好的 Linux 引導程序 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160828  4 Best Linux Boot Loaders","title":"4 個最好的 Linux 引導程序","tag":"201609","desc":""},"relativePath":"201609/20160828  4 Best Linux Boot Loaders.md","filePath":"[post].md"}'),d={name:"201609/20160828  4 Best Linux Boot Loaders.md"};function p(L,l,B,f,T,m){const i=e("Link");return s(),a("div",null,[l[21]||(l[21]=x('<h1 id="_4-個最好的-linux-引導程序" tabindex="-1">4 個最好的 Linux 引導程序 <a class="header-anchor" href="#_4-個最好的-linux-引導程序" aria-label="Permalink to “4 個最好的 Linux 引導程序”">​</a></h1><p>當你打開你的機器，開機自檢（POST）成功完成後，BIOS（基本輸入輸出系統）立即定位所配置的引導介質，並從 MBR（主引導記錄）或 GUID（全局唯一標識符）分區表讀取一些命令，這是引導介質的最前面 512 個字節內容。主引導記錄（MBR）中包含兩個重要的信息集合，第一個是引導程序，第二個是分區表。</p><h3 id="什麼是引導程序" tabindex="-1">什麼是引導程序？ <a class="header-anchor" href="#什麼是引導程序" aria-label="Permalink to “什麼是引導程序？”">​</a></h3><p>引導程序（Boot Loader）是存儲在 MBR（主引導記錄）或 GUID（全局唯一標識符）分區表中的一個小程序，用於幫助把操作系統裝載到內存中。如果沒有引導程序，那麼你的操作系統將不能夠裝載到內存中。</p><p>有一些我們可以隨同 Linux 安裝到系統上的引導程序，在這篇文章裏，我將簡要地談論幾個最好的可以與 Linux 一同工作的 Linux 引導程序。</p><h3 id="_1-gnu-grub" tabindex="-1">1. GNU GRUB <a class="header-anchor" href="#_1-gnu-grub" aria-label="Permalink to “1. GNU GRUB”">​</a></h3><p>GNU GRUB 是一個非常受歡迎，也可能是用的最多的具有多重引導能力的 Linux 引導程序，它以原始的 Eirch Stefan Broleyn 發明的 GRUB（GRand Unified Bootlader）為基礎。GNU GRUB 增強了原來的 GRUB，帶來了一些改進、新的特性和漏洞修復。</p><p>重要的是，GRUB 2 現在已經取代了 GRUB。值得注意的是，GRUB 這個名字被重新命名為 GRUB Legacy，但沒有活躍開發，不過，它可以用來引導老的系統，因為漏洞修復依然繼續。</p><p>GRUB 具有下面一些顯著的特性：</p><ul><li>支持多重引導</li><li>支持多種硬件結構和操作系統，比如 Linux 和 Windows</li><li>提供一個類似 Bash 的交互式命令列界面，從而用户可以運行 GRUB 命令來和配置文件進行交互</li><li>允許訪問 GRUB 編輯器</li><li>支持設置加密口令以確保安全</li><li>支持從網絡進行引導，以及一些次要的特性</li></ul>',10)),t("p",null,[l[1]||(l[1]=n("訪問主頁: ",-1)),r(i,{href:"https://www.gnu.org/software/grub/"},{default:u(()=>[...l[0]||(l[0]=[n("https://www.gnu.org/software/grub/",-1)])]),_:1})]),l[22]||(l[22]=t("h3",{id:"_2-lilo-linux-引導程序-linux-loader",tabindex:"-1"},[n("2. LILO（Linux 引導程序（LInux LOader）） "),t("a",{class:"header-anchor",href:"#_2-lilo-linux-引導程序-linux-loader","aria-label":"Permalink to “2. LILO（Linux 引導程序（LInux LOader））”"},"​")],-1)),l[23]||(l[23]=t("p",null,"LILO 是一個簡單但強大且非常穩定的 Linux 引導程序。由於 GRUB 有很大改善和增加了許多強大的特性，越來越受歡迎，因此 LILO 在 Linux 用户中已經不是很流行了。",-1)),l[24]||(l[24]=t("p",null,"當 LILO 引導的時候，單詞“LILO”會出現在屏幕上，並且每一個字母會在一個特定的事件發生前後出現。然而，從 2015 年 12 月開始，LILO 的開發停止了，它有許多特性比如下面列舉的：",-1)),l[25]||(l[25]=t("ul",null,[t("li",null,"不提供交互式命令列界面"),t("li",null,"支持一些錯誤代碼"),t("li",null,"不支持網絡引導（LCTT 譯註：其變體 ELILO 支持 TFTP/DHCP 引導）"),t("li",null,"所有的文件存儲在驅動的最開始 1024 個柱面上"),t("li",null,"面臨 BTFS、GTP、RAID 等的限制")],-1)),t("p",null,[l[3]||(l[3]=n("訪問主頁: ",-1)),r(i,{href:"http://lilo.alioth.debian.org/"},{default:u(()=>[...l[2]||(l[2]=[n("http://lilo.alioth.debian.org/",-1)])]),_:1})]),l[26]||(l[26]=t("h3",{id:"_3-burg-新的引導程序",tabindex:"-1"},[n("3. BURG - 新的引導程序 "),t("a",{class:"header-anchor",href:"#_3-burg-新的引導程序","aria-label":"Permalink to “3. BURG - 新的引導程序”"},"​")],-1)),l[27]||(l[27]=t("p",null,"基於 GRUB，BURG 是一個相對來説比較新的引導程序（LCTT 譯註：已於 2011 年停止了開發）。由於 BURG 起源於 GRUB, 所以它帶有一些 GRUB 主要特性。儘管如此, BURG 也提供了一些出色的特性，比如一種新的對象格式可以支持包括 Linux、Windows、Mac OS、 FreeBSD 等多種平台。",-1)),l[28]||(l[28]=t("p",null,"另外，BURG 支持可高度配置的文本和圖標模式的引導菜單，計劃增加的“流”支持未來可以不同的輸入/輸出設備一同工作。",-1)),t("p",null,[l[5]||(l[5]=n("訪問主頁: ",-1)),r(i,{href:"https://launchpad.net/burg"},{default:u(()=>[...l[4]||(l[4]=[n("https://launchpad.net/burg",-1)])]),_:1})]),l[29]||(l[29]=t("h3",{id:"_4-syslinux",tabindex:"-1"},[n("4. Syslinux "),t("a",{class:"header-anchor",href:"#_4-syslinux","aria-label":"Permalink to “4. Syslinux”"},"​")],-1)),l[30]||(l[30]=t("p",null,"Syslinux 是一種能從光盤驅動器、網絡等進行引導的輕型引導程序。Syslinux 支持諸如 MS-DOS 上的 FAT、 Linux 上的 ext2、ext3、ext4 等文件系統。Syslinux 也支持未壓縮的單一設備上的 Btrfs。",-1)),l[31]||(l[31]=t("p",null,"注意由於 Syslinux 僅能訪問自己分區上的文件，因此不具備多重文件系統引導能力。",-1)),t("p",null,[l[7]||(l[7]=n("訪問主頁: ",-1)),r(i,{href:"http://www.syslinux.org/wiki/index.php?title=The_Syslinux_Project"},{default:u(()=>[...l[6]||(l[6]=[n("http://www.syslinux.org/wiki/index.php?title=The_Syslinux_Project",-1)])]),_:1})]),l[32]||(l[32]=t("h3",{id:"結論",tabindex:"-1"},[n("結論 "),t("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),l[33]||(l[33]=t("p",null,"一個引導程序允許你在你的機器上管理多個操作系統，並在某個的時間選擇其中一個使用。沒有引導程序，你的機器就不能夠裝載內核以及操作系統的剩餘部分。",-1)),l[34]||(l[34]=t("p",null,"我們是否遺漏了任何一流的 Linux 引導程序？如果有請讓我們知道，請在下面的評論表中填入值得推薦的 Linux 系統引導程序。",-1)),l[35]||(l[35]=t("hr",null,null,-1)),t("p",null,[l[9]||(l[9]=n("via: ",-1)),r(i,{href:"http://www.tecmint.com/best-linux-boot-loaders/"},{default:u(()=>[...l[8]||(l[8]=[n("http://www.tecmint.com/best-linux-boot-loaders/",-1)])]),_:1})]),t("p",null,[l[13]||(l[13]=n("作者：",-1)),r(i,{href:"http://www.tecmint.com/best-linux-boot-loaders/"},{default:u(()=>[...l[10]||(l[10]=[n("Aaron Kili",-1)])]),_:1}),l[14]||(l[14]=n(" 譯者：",-1)),r(i,{href:"https://github.com/ucasFL"},{default:u(()=>[...l[11]||(l[11]=[n("ucasFL",-1)])]),_:1}),l[15]||(l[15]=n(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:u(()=>[...l[12]||(l[12]=[n("wxy",-1)])]),_:1})]),t("p",null,[l[18]||(l[18]=n("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...l[16]||(l[16]=[n("LCTT",-1)])]),_:1}),l[19]||(l[19]=n(" 原創編譯，",-1)),r(i,{href:"https://linux.cn/"},{default:u(()=>[...l[17]||(l[17]=[n("Linux中國",-1)])]),_:1}),l[20]||(l[20]=n(" 榮譽推出",-1))])])}const U=o(d,[["render",p]]);export{G as __pageData,U as default};
